--
-- Table structure for table `conductor_asignacion`
--

DROP TABLE IF EXISTS `conductor_asignacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `conductor_asignacion` (
  `conductor_id` int(11) NOT NULL,
  `vehiculo_id` int(11) DEFAULT NULL,
  `envio_id` int(11) DEFAULT NULL,
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`conductor_id`),
  UNIQUE KEY `vehiculo_id` (`vehiculo_id`),
  UNIQUE KEY `envio_id` (`envio_id`),
  CONSTRAINT `fk_ca_conductor` FOREIGN KEY (`conductor_id`) REFERENCES `colaboradores` (`id_colaborador`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_envio` FOREIGN KEY (`envio_id`) REFERENCES `envios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_vehiculo` FOREIGN KEY (`vehiculo_id`) REFERENCES `vehiculos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

