--
-- Table structure for table `envios`
--

DROP TABLE IF EXISTS `envios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `envios` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_cliente` int(11) NOT NULL,
  `num_guia` varchar(40) DEFAULT NULL,
  `direccion_destino` varchar(255) NOT NULL,
  `ciudad_destino` varchar(100) DEFAULT NULL,
  `estado_destino` varchar(100) DEFAULT NULL,
  `id_sucursal_origen` int(11) DEFAULT NULL,
  `costo` decimal(10,2) DEFAULT 0.00,
  `estatus` enum('recibido','procesado','en_transito','entregado','cancelado') DEFAULT 'recibido',
  `fecha_creacion` datetime DEFAULT current_timestamp(),
  `destinatario_nombre` varchar(150) DEFAULT NULL,
  `destinatario_telefono` varchar(30) DEFAULT NULL,
  `peso` decimal(10,2) DEFAULT 0.00,
  `fecha_actualizacion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `id_colaborador_actualizo` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `num_guia` (`num_guia`),
  KEY `idx_estatus` (`estatus`),
  KEY `idx_id_sucursal_origen` (`id_sucursal_origen`),
  KEY `fk_envios_cliente` (`id_cliente`),
  CONSTRAINT `envios_ibfk_1` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id`),
  CONSTRAINT `envios_ibfk_2` FOREIGN KEY (`id_sucursal_origen`) REFERENCES `sucursales` (`id_sucursal`) ON DELETE SET NULL,
  CONSTRAINT `fk_envios_cliente` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id`) ON UPDATE CASCADE,
